package com.shopstream.catalog;

import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.ThreadLocalRandom;

import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import tools.jackson.databind.json.JsonMapper;

@Service
public class ProductCache {

    private static final Duration BASE_TTL = Duration.ofMinutes(10);

    private final StringRedisTemplate redis;
    private final JsonMapper json;
    private final ProductRepository repository;

    public ProductCache(StringRedisTemplate redis, JsonMapper json,
                        ProductRepository repository) {
        this.redis = redis;
        this.json = json;
        this.repository = repository;
    }

    public Optional<ProductView> find(long id) {
        String key = key(id);
        String cached = redis.opsForValue().get(key);          // 1. look in the cache
        if (cached != null) {
            return Optional.of(json.readValue(cached, ProductView.class));   // 2. hit
        }
        Optional<ProductView> loaded = repository.findViewById(id);         // 3. miss
        loaded.ifPresent(view ->
            redis.opsForValue().set(key, json.writeValueAsString(view), ttlWithJitter())); // 4
        return loaded;                                                       // 5
    }

    public void update(long id, ProductUpdate change) {
        repository.update(id, change);      // 1. database first (the source of truth)
        redis.delete(key(id));              // 2. then invalidate
    }

    private static String key(long id) {
        return "shopstream:v1:product:" + id;
    }

    private static Duration ttlWithJitter() {
        long jitterSeconds = ThreadLocalRandom.current().nextLong(0, 60);
        return BASE_TTL.plusSeconds(jitterSeconds);
    }
}

package com.shopstream.catalog;

import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class CatalogService {

    private final ProductRepository repository;

    public CatalogService(ProductRepository repository) {
        this.repository = repository;
    }

    @Cacheable(cacheNames = "products", key = "#id", unless = "#result == null")
    public ProductView getProduct(long id) {
        return repository.findViewById(id).orElse(null);
    }

    @Transactional
    @CacheEvict(cacheNames = "products", key = "#id")
    public void updateProduct(long id, ProductUpdate change) {
        repository.update(id, change);
    }
}

package com.shopstream.catalog;

import java.util.List;
import java.util.Objects;

import org.springframework.data.redis.core.StringRedisTemplate;

public class ListingCache {

    private final StringRedisTemplate redis;

    public ListingCache(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Resolve a cached page of product ids into cached product JSON in one round trip. */
    public List<String> productJsonForPage(List<Long> idsOnPage) {
        List<String> keys = idsOnPage.stream()
            .map(id -> "shopstream:v1:product:" + id)
            .toList();
        List<String> values = redis.opsForValue().multiGet(keys);   // MGET
        // null entries are per-product misses: load those from the database and fill them
        return values == null ? List.of() : values.stream().filter(Objects::nonNull).toList();
    }
}

package com.shopstream.catalog;
import java.time.Duration;
import java.util.Optional;
import java.util.UUID;
import java.util.function.Supplier;
import org.springframework.data.redis.core.StringRedisTemplate;
public class StampedeGuard {
    private final StringRedisTemplate redis;
    public StampedeGuard(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Returns the cached string, or rebuilds it once across all instances. */
    public String getOrLoad(String key, Duration ttl, Supplier<String> loader)
            throws InterruptedException {
        for (int attempt = 0; attempt < 20; attempt++) {
            String cached = redis.opsForValue().get(key);
            if (cached != null) {
                return cached;
            }
            String lockKey = "lock:" + key;
            String token = UUID.randomUUID().toString();
            Boolean won = redis.opsForValue()
                .setIfAbsent(lockKey, token, Duration.ofSeconds(5));
            if (Boolean.TRUE.equals(won)) {
                try {
                    String again = redis.opsForValue().get(key);   // double-check after winning
                    if (again != null) {
                        return again;                              // someone filled it meanwhile
                    }
                    String value = loader.get();                 // only the winner hits the DB
                    redis.opsForValue().set(key, value, ttl);
                    return value;
                } finally {
                    // release only our own lock (compare-and-delete, see the locks chapter)
                    if (token.equals(redis.opsForValue().get(lockKey))) {
                        redis.delete(lockKey);
                    }
                }
            }
            Thread.sleep(25 + (long) (Math.random() * 25));       // lost: wait, then re-read
        }
        return loader.get();   // lock holder is slow or dead: fall back to loading directly
    }
}

package com.shopstream.catalog;

import java.time.Duration;
import java.util.Optional;

import org.springframework.data.redis.core.StringRedisTemplate;
import tools.jackson.databind.json.JsonMapper;

public class NegativeCaching {

    private static final String NOT_FOUND = "__NULL__";

    private final StringRedisTemplate redis;
    private final JsonMapper json;
    private final ProductRepository repository;

    public NegativeCaching(StringRedisTemplate redis, JsonMapper json,
                           ProductRepository repository) {
        this.redis = redis;
        this.json = json;
        this.repository = repository;
    }

    public Optional<ProductView> find(long id) {
        String key = "shopstream:v1:product:" + id;
        String cached = redis.opsForValue().get(key);
        if (NOT_FOUND.equals(cached)) {
            return Optional.empty();                               // known to be missing
        }
        if (cached != null) {
            return Optional.of(json.readValue(cached, ProductView.class));
        }
        Optional<ProductView> loaded = repository.findViewById(id);
        if (loaded.isPresent()) {
            redis.opsForValue().set(key, json.writeValueAsString(loaded.get()),
                Duration.ofMinutes(10));
        } else {
            redis.opsForValue().set(key, NOT_FOUND, Duration.ofSeconds(45)); // short TTL
        }
        return loaded;
    }
}

package com.shopstream.catalog;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;

@SpringBootTest
class StampedeGuardTest {

    @Autowired
    StringRedisTemplate redis;

    @Test
    void onlyOneCallerRebuildsTheValue() throws Exception {
        redis.delete("demo:hot");
        StampedeGuard guard = new StampedeGuard(redis);
        AtomicInteger loaderCalls = new AtomicInteger();

        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<String>> results = new ArrayList<>();
            for (int i = 0; i < 200; i++) {
                results.add(pool.submit(() -> guard.getOrLoad("demo:hot",
                    Duration.ofSeconds(30), () -> {
                    loaderCalls.incrementAndGet();
                    sleep(300);                       // pretend the database query is slow
                    return "value";
                })));
            }
            for (Future<String> f : results) {
                assertEquals("value", f.get());
            }
        }
        assertEquals(1, loaderCalls.get());
    }

    private static void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

package com.shopstream.locks;

import java.time.Duration;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;

public class RedisLock {

    private static final DefaultRedisScript<Long> UNLOCK = new DefaultRedisScript<>("""
        if redis.call('GET', KEYS[1]) == ARGV[1] then
          return redis.call('DEL', KEYS[1])
        else
          return 0
        end
        """, Long.class);

    private final StringRedisTemplate redis;

    public RedisLock(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Returns a token if the lock was acquired, otherwise empty. */
    public Optional<String> tryLock(String name, Duration ttl) {
        String token = UUID.randomUUID().toString();
        Boolean ok = redis.opsForValue().setIfAbsent("lock:" + name, token, ttl);
        return Boolean.TRUE.equals(ok) ? Optional.of(token) : Optional.empty();
    }

    /** Releases the lock only if we still own it. Returns true if we did. */
    public boolean unlock(String name, String token) {
        Long deleted = redis.execute(UNLOCK, List.of("lock:" + name), token);
        return deleted != null && deleted == 1L;
    }
}

package com.shopstream.orders;
import java.time.Duration;
import java.util.Optional;
import com.shopstream.locks.RedisLock;
import org.springframework.stereotype.Service;
@Service
public class OrderProcessor {
    private final RedisLock lock;
    public OrderProcessor(RedisLock lock) {
        this.lock = lock;
    }

    public void process(long orderId) {
        String name = "order:" + orderId;
        Optional<String> token = lock.tryLock(name, Duration.ofSeconds(30));
        if (token.isEmpty()) {
            return;                       // someone else is on it: skip, retry later, or fail fast
        }
        try {
            // do the work: must finish well inside the 30 seconds
        } finally {
            lock.unlock(name, token.get());
        }
    }
}

package com.shopstream.orders;
import java.util.concurrent.TimeUnit;
import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;
import org.springframework.stereotype.Service;
@Service
public class RedissonOrderProcessor {
    private final RedissonClient redisson;
    public RedissonOrderProcessor(RedissonClient redisson) {
        this.redisson = redisson;
    }

    public void process(long orderId) throws InterruptedException {
        RLock lock = redisson.getLock("lock:order:" + orderId);
        // wait up to 2 seconds to get the lock; no lease time => watchdog keeps it alive
        if (!lock.tryLock(2, TimeUnit.SECONDS)) {
            return;                               // could not get it in time
        }
        try {
            // critical section
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}

package com.shopstream.locks;

import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.ThreadLocalRandom;

public class WaitingLock {

    private final RedisLock lock;

    public WaitingLock(RedisLock lock) {
        this.lock = lock;
    }

    public Optional<String> lockWithin(String name, Duration ttl, Duration maxWait)
            throws InterruptedException {
        long deadline = System.nanoTime() + maxWait.toNanos();
        long sleepMillis = 10;
        while (System.nanoTime() < deadline) {
            Optional<String> token = lock.tryLock(name, ttl);
            if (token.isPresent()) {
                return token;
            }
            long jitter = ThreadLocalRandom.current().nextLong(sleepMillis / 2 + 1);
            Thread.sleep(sleepMillis + jitter);
            sleepMillis = Math.min(sleepMillis * 2, 200);     // back off, but cap the pause
        }
        return Optional.empty();
    }
}

package com.shopstream.locks;

import java.time.Duration;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;

public class LeaseHolder implements AutoCloseable {

    private static final DefaultRedisScript<Long> EXTEND = new DefaultRedisScript<>("""
        if redis.call('GET', KEYS[1]) == ARGV[1] then
          return redis.call('PEXPIRE', KEYS[1], ARGV[2])
        else
          return 0
        end
        """, Long.class);

    private final ScheduledExecutorService scheduler =
        Executors.newSingleThreadScheduledExecutor();
    private final AtomicBoolean lost = new AtomicBoolean(false);
    private final ScheduledFuture<?> renewal;

    public LeaseHolder(StringRedisTemplate redis, String key, String token, Duration ttl) {
        long ttlMillis = ttl.toMillis();
        this.renewal = scheduler.scheduleAtFixedRate(() -> {
            Long ok = redis.execute(EXTEND, List.of(key), token, String.valueOf(ttlMillis));
            if (ok == null || ok == 0L) {
                lost.set(true);                    // we no longer own the lock
                renewal().cancel(false);
            }
        }, ttlMillis / 3, ttlMillis / 3, TimeUnit.MILLISECONDS);
    }

    private ScheduledFuture<?> renewal() {
        return renewal;
    }

    /** The job should check this between steps and stop when it turns true. */
    public boolean isLost() {
        return lost.get();
    }

    @Override
    public void close() {
        scheduler.shutdownNow();
    }
}

package com.shopstream.gateway.ratelimit;

import java.util.List;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

@Component
public class TokenBucketRateLimiter {

    public record Decision(boolean allowed, long remaining, long retryAfterMs) {}
    private final StringRedisTemplate redis;
    private final DefaultRedisScript<List> script;

    public TokenBucketRateLimiter(StringRedisTemplate redis) {
        this.redis = redis;
        this.script = new DefaultRedisScript<>();
        this.script.setLocation(new ClassPathResource("scripts/token_bucket.lua"));
        this.script.setResultType(List.class);
    }

    public Decision tryAcquire(String key, int capacity, double refillPerSec, int cost) {
        List<?> reply = redis.execute(script, List.of(key),
                String.valueOf(capacity), String.valueOf(refillPerSec), String.valueOf(cost));
        if (reply == null || reply.size() < 3) {
            return new Decision(true, capacity, 0);   // fail open on a malformed reply
        }
        return new Decision(
                ((Number) reply.get(0)).longValue() == 1L,
                ((Number) reply.get(1)).longValue(),
                ((Number) reply.get(2)).longValue());
    }
}

package com.shopstream.gateway.ratelimit;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
public class RateLimitFilter extends OncePerRequestFilter {

    private static final int CAPACITY = 20;
    private static final double REFILL_PER_SEC = 5.0;

    private final TokenBucketRateLimiter limiter;

    public RateLimitFilter(TokenBucketRateLimiter limiter) {
        this.limiter = limiter;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        String key = "rl:" + request.getRemoteAddr() + ":" + request.getRequestURI();

        TokenBucketRateLimiter.Decision d;
        try {
            d = limiter.tryAcquire(key, CAPACITY, REFILL_PER_SEC, 1);
        } catch (RuntimeException redisDown) {
            chain.doFilter(request, response);      // fail open
            return;
        }

        response.setHeader("RateLimit-Limit", String.valueOf(CAPACITY));
        response.setHeader("RateLimit-Remaining", String.valueOf(d.remaining()));
        if (!d.allowed()) {
            long seconds = Math.max(1, (d.retryAfterMs() + 999) / 1000);
            response.setHeader("Retry-After", String.valueOf(seconds));
            response.setStatus(429);
            response.getWriter().write("{\"error\":\"rate_limited\"}");
            return;
        }
        chain.doFilter(request, response);
    }
}
